    S.articles = [
      { id: "a1", slug: "building-for-the-smallholder", seed: "indigo", type: "Interview", title: "Building for the smallholder: how Savanna Loop thinks about scale", industry: "Agriculture & Agritech", author: "Sade Mwale-Okafor", date: "2026-11-03", status: "published", sponsor: null, relatedEvent: "ev1", profiles: ["b1", "ip2"], lede: "Fictional interview. A conversation about why software for farmers has to start with the cooperative, not the phone.", body: "Most agricultural software assumes a farmer with a smartphone and a data plan. Savanna Loop started somewhere else: with the cooperative secretary who keeps the group's records in an exercise book.", paras: ["The company's first product was a weekly printed sheet, generated from satellite data and delivered through cooperative meetings. The app came later, and it was built for the secretary rather than the farmer.", "That order mattered. By the time the software arrived, the cooperatives already trusted the advice, because it had been right about planting dates for two seasons in a row.", "The harder problem now is money. Cooperatives can see that better planning raises yields, but paying for it means changing how a group collects and holds its savings."], quote: "We did not set out to digitise farmers. We set out to be useful to the person who already keeps the records." },
      { id: "a2", slug: "route-planning-on-bad-roads", seed: "mesa", type: "Feature", title: "Route planning on bad roads: what freight data can and cannot fix", industry: "Technology", author: "WHOISWHO Stories", date: "2026-11-02", status: "published", sponsor: null, relatedEvent: "ev2", profiles: ["b3"], lede: "Fictional feature. Logistics firms are rich in data and short on certainty. Here is what they do about it.", body: "A route that takes nine hours in January can take twenty in July. Freight operators in the Niger Delta have learned to plan for the range, not the average.", paras: ["Bonny Reach Logistics now records every delay against a cause, from a washed-out culvert to a closed market. Three years of those records have changed which routes it offers and when.", "Software cannot fix the road. It can tell a customer on Monday what Friday will probably look like, and for most of them that is worth paying for."], quote: "We stopped promising arrival times. We started promising ranges, and complaints went down." },
      { id: "a3", slug: "merchant-settlement-spotlight", seed: "laterite", type: "Spotlight", title: "Same-day settlement and the small merchant", industry: "Financial Services & Fintech", author: "WHOISWHO Stories", date: "2026-11-04", status: "published", sponsor: null, profiles: ["b2", "ip4"], lede: "Fictional sponsored spotlight. A look at what faster settlement changes for a market trader.", body: "For a trader buying stock every morning, money that arrives tomorrow is money that did not arrive. Settlement speed decides how much she can buy.", paras: ["Tiderail Payments built its service around that morning purchase. Merchants see the day's takings settled by the close of business, with a statement a bookkeeper can read.", "This story is sponsored. The sponsor did not write it, did not review it, and has no influence over the labels on any profile mentioned here."], quote: "Faster money changes what a small business can plan for." },
      { id: "a4", slug: "soil-before-software", seed: "canopy", type: "Opinion", title: "Soil before software: a case for slower agricultural innovation", industry: "Education", author: "Prof. Kofi Adeleke-Nkosi", date: "2026-10-30", status: "published", sponsor: null, profiles: ["ip5"], lede: "Fictional opinion. The fastest way to help a farm is often the oldest one: find out what the soil needs.", body: "We have more ways than ever to tell a farmer what to do, and no more certainty that the advice fits the ground under their feet.", paras: ["A soil test costs little and lasts for years. Yet most extension programmes still lead with an app, because an app is easier to count.", "Better measurement should come first. The software can follow, and it will work better when it does."], quote: "An app is easier to count than a healthier field." },
      { id: "a5", slug: "introducing-the-maiden-edition", seed: "adire", type: "Announcement", title: "Introducing the Maiden Edition", industry: "Media & Creative", author: "WHOISWHO Stories", date: "2026-11-01", status: "published", sponsor: null, profiles: [], lede: "Fictional announcement. What the first WHOISWHO edition is, how recognition works, and when nominations open.", body: "The Maiden Edition is the first public record from WHOISWHO: a reviewed directory of the people, businesses and institutions shaping Africa, starting in Nigeria.", paras: ["Recognition follows the same discipline as the directory. Categories and rules are published before nominations open, and no payment or sponsorship can affect the outcome.", "Nominations open once the rules are published. Anyone can leave an email address to be told when they do."], quote: "Rules first. Nominations second. Outcomes that money cannot touch." },
      { id: "a6", slug: "primary-care-spotlight", seed: "quarry", type: "News", title: "Confluence Health Network opens two new outpatient clinics", industry: "Health & Life Sciences", author: "WHOISWHO Stories", date: "2026-11-05", status: "published", sponsor: null, profiles: ["b4"], lede: "Fictional news item. The network extends maternal health services to two more communities.", body: "Confluence Health Network has opened two outpatient clinics, extending its maternal health services to communities that previously travelled to the capital for routine care.", paras: ["The clinics will offer antenatal checks, vaccination and basic diagnostics, with referrals to the network's main site for anything more complex."], quote: "" },
      { id: "a7", slug: "scheduled-feature-diagnostics", seed: "plateau", type: "Feature", title: "The diagnostic gap in secondary cities", industry: "Health & Life Sciences", author: "WHOISWHO Stories", date: "2026-11-20", status: "scheduled", sponsor: null, profiles: [], lede: "Scheduled for later; not public yet.", body: "Scheduled for later; not public yet.", paras: [], quote: "" },
    ];
